import defsJson from './topicDefs.json'
import factsIndexJson from './factsIndex.json'
import { ORG_FACTS, displayCount } from '../orgFacts'

/**
 * The impact library (/impact/<slug>): shared logic for the app (public/TopicPage.tsx, the /impact hub, the
 * project-page "part of" card) and for scripts/prerender-meta.mjs, which bundles this file with esbuild.
 *
 *   topicDefs.json    which drives belong to which page (hand-kept)
 *   facts/<slug>.json counts and drive lists (generated by scripts/compute-topic-facts.mjs on every build)
 *   factsIndex.json   one line per topic (generated, same script)
 *   copy/<slug>.json  the words (written once from the drive records, then edited by hand like any copy)
 *
 * The copy never types a count. It writes tokens ({count}, {volunteers}, {year:2024}, {count:other-slug},
 * {members} ...) that fillTokens() replaces from the generated facts, so every number moves with the database.
 */

export interface TopicDef {
  slug: string
  group: string
  label: string
  match: { header?: string; location?: string; text?: string; year?: number; month?: string; blog?: string; all?: boolean }
  related: string[]
}
export interface TopicGroup { id: string; name: string }

export interface TopicDrive { slug: string; title: string; date: string | null; place: string | null; img?: string; alt?: string }
export interface TopicFacts {
  slug: string
  count: number
  volunteers: number
  firstDate: string | null
  lastDate: string | null
  byYear: Record<string, number>
  placesCount: number
  topPlaces: { name: string; count: number }[]
  drives: TopicDrive[]
  posts?: { slug: string; title: string; date: string | null; excerpt: string }[]
}
export interface TopicCopy {
  slug: string
  title: string
  description: string
  h1Lead: string
  h1Accent: string
  lede: string
  sections: { id: string; heading: string; body: string[] }[]
  learnings?: string[]
  faqs: { q: string; a: string }[]
  keywords?: string[]
}
interface IndexLine { count: number; volunteers: number; firstYear: number | null; lastYear: number | null }

export const TOPIC_GROUPS: TopicGroup[] = (defsJson as { groups: TopicGroup[] }).groups
export const TOPICS: TopicDef[] = (defsJson as { topics: TopicDef[] }).topics
export const TOPIC_INDEX = factsIndexJson as unknown as Record<string, IndexLine>
export const TOPIC_BY_SLUG: Record<string, TopicDef> = Object.fromEntries(TOPICS.map(t => [t.slug, t]))

export const topicPath = (slug: string) => `/impact/${slug}`
const ORIGIN = 'https://www.ngoaquaterra.com'

/** Topics whose page lists every drive (guides, where-we-work): their drive list is a "latest" sample, not the topic. */
export const isWholeOrgTopic = (t: TopicDef) => !!t.match.all

const n = (v: number | null | undefined) => (typeof v === 'number' ? v.toLocaleString('en-IN') : '')

function yearsPhrase(first: number | null, last: number | null): string {
  if (!first) return ''
  if (!last || last === first) return String(first)
  return `${first} to ${last}`
}

/**
 * Replace every {token} in a copy string. Unknown tokens are removed rather than shown raw, and logged in dev,
 * so a typo can never print "{cuont}" on a live page.
 */
export function fillTokens(text: string, facts: Pick<TopicFacts, 'count' | 'volunteers' | 'firstDate' | 'lastDate' | 'byYear' | 'placesCount' | 'topPlaces'>): string {
  const firstYear = facts.firstDate ? Number(facts.firstDate.slice(0, 4)) : null
  const lastYear = facts.lastDate ? Number(facts.lastDate.slice(0, 4)) : null
  const org: Record<string, string> = {
    members: displayCount(ORG_FACTS.membersTotal),
    drives: displayCount(ORG_FACTS.drivesWrittenUp),
    children: displayCount(ORG_FACTS.childrenReached),
    saplings: displayCount(ORG_FACTS.saplingsPlanted),
    bananas: displayCount(ORG_FACTS.bananasDistributed),
    checkups: displayCount(ORG_FACTS.medicalCheckups),
    dogMeals: displayCount(ORG_FACTS.dogMealsServed),
    sundarbansTrips: String(ORG_FACTS.sundarbansTrips),
    clothesKg: n(ORG_FACTS.clothesDistributedKg),
  }
  const local: Record<string, string> = {
    count: n(facts.count),
    volunteers: n(facts.volunteers),
    firstYear: firstYear ? String(firstYear) : '',
    lastYear: lastYear ? String(lastYear) : '',
    years: yearsPhrase(firstYear, lastYear),
    placesCount: n(facts.placesCount),
    topPlace: facts.topPlaces[0]?.name || 'Kolkata',
  }
  return text.replace(/\{([a-zA-Z]+)(?::([a-z0-9-]+))?\}/g, (whole, key: string, arg?: string) => {
    if (arg !== undefined) {
      if (key === 'year') return n(facts.byYear[arg] || 0)
      const line = TOPIC_INDEX[arg]
      if (line && key === 'count') return n(line.count)
      if (line && key === 'volunteers') return n(line.volunteers)
    } else {
      if (key in local) return local[key]
      if (key in org) return org[key]
    }
    if (typeof process === 'undefined' && import.meta.env?.DEV) console.warn(`[topics] unknown token ${whole}`)
    return ''
  })
}

/** Inline markdown links in copy: [label](/path). Only site-relative paths are honoured. */
export type Piece = { text: string; href?: string }
export function splitLinks(text: string): Piece[] {
  const out: Piece[] = []
  const re = /\[([^\]]+)\]\((\/[a-z0-9\-/#]*)\)/gi
  let last = 0
  let m: RegExpExecArray | null
  while ((m = re.exec(text))) {
    if (m.index > last) out.push({ text: text.slice(last, m.index) })
    out.push({ text: m[1], href: m[2] })
    last = m.index + m[0].length
  }
  if (last < text.length) out.push({ text: text.slice(last) })
  return out
}
export const stripLinks = (text: string) => splitLinks(text).map(p => p.text).join('')

/** Which library pages a single drive belongs to (for the "part of" card on /projects/:slug). Series first. */
export function topicsForDrive(drive: { header?: string | null; location?: string | null; short_summary?: string | null; objective?: string | null; workshop_date?: string | null }): TopicDef[] {
  const clean = (s?: string | null) => String(s || '').replace(/\s+/g, ' ').trim()
  const hits = TOPICS.filter(t => {
    const m = t.match
    if (m.all) return false
    if (m.year) return drive.workshop_date ? new Date(drive.workshop_date).getUTCFullYear() === m.year : false
    if (m.month) return drive.workshop_date ? drive.workshop_date.slice(0, 7) === m.month : false
    if (m.header && new RegExp(m.header, 'i').test(clean(drive.header))) return true
    if (m.location && new RegExp(m.location, 'i').test(clean(drive.location))) return true
    if (m.text && new RegExp(m.text, 'i').test(`${clean(drive.header)} ${clean(drive.short_summary)} ${clean(drive.objective)}`)) return true
    return false
  })
  const order = TOPIC_GROUPS.map(g => g.id)
  return hits.sort((a, b) => order.indexOf(a.group) - order.indexOf(b.group))
}

/**
 * Structured data for one topic page: a CollectionPage whose mainEntity is the ItemList of the drives it covers
 * (each pointing at its own write-up), the FAQPage with the same questions the page shows, and a breadcrumb.
 */
export function buildTopicJsonLd(def: TopicDef, copy: TopicCopy, facts: TopicFacts, title: string, description: string): object[] {
  const url = `${ORIGIN}${topicPath(def.slug)}`
  const drives = isWholeOrgTopic(def) ? facts.drives.slice(0, 12) : facts.drives
  return [
    {
      '@context': 'https://schema.org',
      '@type': 'CollectionPage',
      '@id': `${url}#page`,
      url,
      name: title,
      headline: fillTokens(`${copy.h1Lead} ${copy.h1Accent}`, facts),
      description,
      inLanguage: 'en-IN',
      isPartOf: { '@type': 'WebSite', name: 'AquaTerra', url: `${ORIGIN}/` },
      publisher: { '@type': 'Organization', name: 'NGO AquaTerra', url: `${ORIGIN}/` },
      about: (copy.keywords || [def.label]).map(k => ({ '@type': 'Thing', name: k })),
      ...(facts.lastDate ? { dateModified: facts.lastDate } : {}),
      ...(facts.topPlaces.length ? { spatialCoverage: facts.topPlaces.slice(0, 5).map(p => ({ '@type': 'Place', name: p.name, containedInPlace: { '@type': 'City', name: 'Kolkata' } })) } : {}),
      relatedLink: def.related.map(r => `${ORIGIN}${topicPath(r)}`),
      mainEntity: {
        '@type': 'ItemList',
        name: def.label,
        numberOfItems: facts.count || facts.posts?.length || 0,
        itemListOrder: 'https://schema.org/ItemListOrderDescending',
        itemListElement: facts.posts?.length && !facts.count
          ? facts.posts.map((p, i) => ({ '@type': 'ListItem', position: i + 1, url: `${ORIGIN}/blog/${p.slug}`, name: p.title }))
          : drives.map((d, i) => ({
            '@type': 'ListItem',
            position: i + 1,
            url: `${ORIGIN}/projects/${d.slug}`,
            name: d.title,
          })),
      },
    },
    {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      '@id': `${url}#faq`,
      mainEntity: copy.faqs.map(f => ({
        '@type': 'Question',
        name: fillTokens(f.q, facts),
        acceptedAnswer: { '@type': 'Answer', text: stripLinks(fillTokens(f.a, facts)) },
      })),
    },
    {
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Home', item: `${ORIGIN}/` },
        { '@type': 'ListItem', position: 2, name: 'How we give back', item: `${ORIGIN}/impact` },
        { '@type': 'ListItem', position: 3, name: def.label, item: url },
      ],
    },
  ]
}

/** The page as plain text, for llms-full.txt. Same words as the page. */
export function topicToText(def: TopicDef, copy: TopicCopy, facts: TopicFacts): string {
  const f = (s: string) => stripLinks(fillTokens(s, facts))
  const out = [`## ${def.label}`, '', `URL: ${ORIGIN}${topicPath(def.slug)}`, '', f(copy.lede), '']
  for (const s of copy.sections) out.push(`### ${f(s.heading)}`, '', ...s.body.flatMap(b => [f(b), '']))
  if (copy.learnings?.length) out.push('What we learned:', ...copy.learnings.map(l => `- ${f(l)}`), '')
  for (const q of copy.faqs) out.push(`Q: ${f(q.q)}`, `A: ${f(q.a)}`, '')
  return out.join('\n')
}
